    Bug 1976565 - Enable copy from commonDialog. r=aleca


    Thunderbird overrides toolkit's common dialog with an XHTML variant. When
    "Copy" is invoked from the context menu, the selection is lost, so nothing gets copied.

    To test, paste this into a console window:

    let w = Services.wm.getMostRecentWindow("mail:3pane");
    Services.prompt.alert(w, "Test error", "Here is an error message.\nTry right-click â†’ Copy.");

    Differential Revision: https://phabricator.services.mozilla.com/D262528

diff --git a/mail/base/content/dialogShadowDom.js b/mail/base/content/dialogShadowDom.js
index 66bad49f19a..38345517114 100644
--- a/mail/base/content/dialogShadowDom.js
+++ b/mail/base/content/dialogShadowDom.js
@@ -12,3 +12,64 @@ window.addEventListener("load", () => {
   link.setAttribute("href", "chrome://messenger/skin/themeableDialog.css");
   document.querySelector("dialog").shadowRoot.appendChild(link);
 });
+
+/**
+ * Wait for the content to load before enabling right-click context menu to
+ * select and copy the text.
+ */
+window.addEventListener(
+  "DOMContentLoaded",
+  () => {
+    if (document.documentElement?.id !== "commonDialogWindow") {
+      return;
+    }
+
+    function getSelectedText() {
+      return window.getSelection?.()?.toString() ?? "";
+    }
+
+    // Cache the selection at the start of the context-menu gesture
+    // because the selection can be lost by the time the menuitem is clicked.
+    let cachedSelectionText = "";
+    window.addEventListener(
+      "contextmenu",
+      () => {
+        cachedSelectionText = getSelectedText();
+      },
+      true
+    );
+
+    function copyToClipboard(text) {
+      if (!text) {
+        return;
+      }
+      try {
+        Cc["@mozilla.org/widget/clipboardhelper;1"]
+          .getService(Ci.nsIClipboardHelper)
+          .copyString(text);
+      } catch {}
+    }
+
+    const copyController = {
+      supportsCommand(command) {
+        return command === "cmd_copy";
+      },
+      isCommandEnabled(command) {
+        if (command === "cmd_copy") {
+          return !!(getSelectedText() || cachedSelectionText);
+        }
+        return false;
+      },
+      doCommand(command) {
+        if (command === "cmd_copy") {
+          const text = getSelectedText() || cachedSelectionText;
+          copyToClipboard(text);
+        }
+      },
+      onEvent() {},
+    };
+
+    window.controllers?.insertControllerAt(0, copyController);
+  },
+  { once: true }
+);
